#!/usr/bin/env php
<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/push_notifications.php';
$options=getopt('',['limit:','dry-run','notification-id:']);$limit=max(1,min(100,(int)($options['limit']??25)));$dry=array_key_exists('dry-run',$options);$notificationId=isset($options['notification-id'])?max(1,(int)$options['notification-id']):null;$cfg=push_config();
$report=['mode'=>$dry?'dry-run':'send','synchronized'=>0,'claimed'=>0,'sent'=>0,'temporary_failures'=>0,'invalidated'=>0,'skipped'=>0];
if(!$cfg['enabled']){echo json_encode($report+['status'=>'disabled'],JSON_UNESCAPED_SLASHES).PHP_EOL;exit(0);}if(!$cfg['encryption_ready']||!$cfg['dependency_ready']||$cfg['vapid_public']===''||$cfg['vapid_private']===''||$cfg['vapid_subject']===''){fwrite(STDERR,json_encode($report+['status'=>'configuration-unavailable']).PHP_EOL);exit(2);}
try{
 $dir=$cfg['store'];if(!is_dir($dir))mkdir($dir,0700,true);$lease=fopen($dir.'/worker.lock','c+');if(!$lease||!flock($lease,LOCK_EX|LOCK_NB)){echo json_encode($report+['status'=>'worker-busy']).PHP_EOL;exit(0);} $subscriptions=json_decode((string)@file_get_contents($dir.'/subscriptions.json'),true)?:[];$queueFile=$dir.'/deliveries.json';$queue=json_decode((string)@file_get_contents($queueFile),true)?:[];$known=[];foreach($queue as $q)$known[$q['notification_id'].':'.$q['subscription_id']]=true;
 $db=get_db();$sql="SELECT n.id,n.notification_type,st.user_id FROM portal_notifications n JOIN portal_notification_status st ON st.notification_id=n.id JOIN users u ON u.id=st.user_id JOIN roles r ON r.id=u.role_id WHERE st.status='unread' AND u.status='active' AND r.name='employee' AND n.created_at>=datetime('now','-7 days')";$args=[];if($notificationId){$sql.=' AND n.id=?';$args[]=$notificationId;}$sql.=' ORDER BY n.id LIMIT 500';$s=$db->prepare($sql);$s->execute($args);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$now=gmdate(DATE_ATOM);
 foreach($rows as $n)foreach($subscriptions as $sub)if((int)$sub['user_id']===(int)$n['user_id']&&$sub['status']==='active'){ $key=$n['id'].':'.$sub['id'];if(isset($known[$key]))continue;$queue[]=['notification_id'=>(int)$n['id'],'subscription_id'=>$sub['id'],'status'=>'pending','attempt_count'=>0,'next_attempt_at'=>$now,'created_at'=>$now];$known[$key]=true;$report['synchronized']++;}
 $eligible=[];foreach($queue as $i=>$q)if($q['status']==='pending'&&strcmp((string)$q['next_attempt_at'],$now)<=0){$eligible[$i]=$q;if(count($eligible)>=$limit)break;}$report['claimed']=count($eligible);if($dry){echo json_encode($report+['status'=>'ok'],JSON_UNESCAPED_SLASHES).PHP_EOL;flock($lease,LOCK_UN);exit(0);}
 require $cfg['store'].'/../../vendor/autoload.php';$webPush=new Minishlink\WebPush\WebPush(['VAPID'=>['subject'=>$cfg['vapid_subject'],'publicKey'=>$cfg['vapid_public'],'privateKey'=>$cfg['vapid_private']]]);
 foreach($eligible as $i=>$q){$sub=null;foreach($subscriptions as $candidate)if($candidate['id']===$q['subscription_id']){$sub=$candidate;break;}if(!$sub){$queue[$i]['status']='invalid';$report['invalidated']++;continue;}$check=$db->prepare("SELECT n.notification_type FROM portal_notifications n JOIN portal_notification_status st ON st.notification_id=n.id WHERE n.id=? AND st.user_id=? AND st.status='unread'");$check->execute([$q['notification_id'],$sub['user_id']]);$type=$check->fetchColumn();if(!$type){$queue[$i]['status']='skipped';$report['skipped']++;continue;}$message=match((string)$type){'assignment'=>'New task assigned','returned'=>'Work returned for correction','due_today'=>'Task due today',default=>'Work notification available'};$payload=json_encode(['notification_id'=>$q['notification_id'],'title'=>'Dakshayani Work','message'=>$message,'category'=>'task']);$subscription=Minishlink\WebPush\Subscription::create(['endpoint'=>push_decrypt($sub['endpoint']),'publicKey'=>push_decrypt($sub['p256dh']),'authToken'=>push_decrypt($sub['auth']),'contentEncoding'=>'aes128gcm']);$webPush->queueNotification($subscription,$payload);$queue[$i]['status']='sending';$queue[$i]['attempt_count']++;}
 foreach($webPush->flush() as $result){$hash=hash('sha256',$result->getRequest()->getUri()->__toString());foreach($queue as $i=>$q){if($q['status']!=='sending')continue;$sub=null;foreach($subscriptions as $candidate)if($candidate['id']===$q['subscription_id'])$sub=$candidate;if(!$sub||!hash_equals($sub['endpoint_hash'],$hash))continue;if($result->isSuccess()){$queue[$i]['status']='sent';$queue[$i]['sent_at']=$now;$report['sent']++;}else{$code=(int)$result->getResponse()?->getStatusCode();if(in_array($code,[404,410],true)){$queue[$i]['status']='invalid';$report['invalidated']++;}else{$queue[$i]['status']='pending';$queue[$i]['next_attempt_at']=gmdate(DATE_ATOM,time()+min(86400,60*(2**min(8,$queue[$i]['attempt_count']))));$report['temporary_failures']++;}}}}
 file_put_contents($queueFile,json_encode($queue,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);chmod($queueFile,0600);echo json_encode($report+['status'=>'ok'],JSON_UNESCAPED_SLASHES).PHP_EOL;flock($lease,LOCK_UN);exit($report['temporary_failures']?1:0);
}catch(Throwable $e){fwrite(STDERR,json_encode($report+['status'=>'worker-failed']).PHP_EOL);exit(2);}
